import{XO_CONFIG as s,UNITS_TO_METRES as y}from"./config.min.js";export function jumpLift(t){const o=s.pose.jump;if(!(t>=0)||t>=1)return 0;const r=typeof o.peakAt=="number"?o.peakAt:.5,n=Math.min(.95,Math.max(.05,r)),e=t<n?.5*(t/n):.5+.5*((t-n)/(1-n));return Math.sin(Math.PI*e)*o.lift}export function spanOf(t){const o=t||{};if(!(o.startX!==void 0&&o.targetX!==void 0))return null;const r=Math.hypot(o.targetX-o.startX,o.targetY-o.startY);return r>0?{sx:o.startX,sy:o.startY,tx:o.targetX,ty:o.targetY,total:r,reach:Math.min(1,r*y/s.ball.fullArcAt)}:null}export function arcHeightAt(t,o,r){const n=s.ball,e=Math.hypot(o-t.sx,r-t.sy),u=Math.min(1,Math.max(0,e/t.total));return n.release+4*u*(1-u)*n.apex*t.reach}export function ballHeight(t){if(!t||!t.coords)return s.ball.release;const o=spanOf(t.coords);return o?arcHeightAt(o,t.coords.x,t.coords.y):s.ball.release}export function inTheAir(t){return t>=0&&t<s.pose.jump.hang}export function handsAt(t,o){const r=o/s.pose.jump.hang;return t+jumpLift(r)}export function leapCatches(t,o,r){return inTheAir(o)?typeof t!="number"?!0:r<=handsAt(t,o)+s.pose.jump.manual.slack:!1}export function nearestToBall(t,o,r){let n=null;for(const e of o||[]){if(!e||!e.coords)continue;const u=arrivalIn(t,e,r),a=t&&t.coords?Math.hypot(e.coords.x-t.coords.x,e.coords.y-t.coords.y):1/0;(!n||u<n.when||u===n.when&&a<n.now)&&(n={r:e,when:u,now:a})}return n?n.r:null}export function arrivalIn(t,o,r){if(!t||!o||!t.coords||!o.coords)return 1/0;const n=r||0,e=o.coords.x,u=o.coords.y;if(Math.hypot(e-t.coords.x,u-t.coords.y)<=n)return 0;const a=Array.isArray(t.coords.list)?t.coords.list:[],h=o.state&&o.state.xSpeed||0,x=o.state&&o.state.ySpeed||0;for(let i=0;i<a.length;i+=1){const p=a[i],f=i+1;if(Math.hypot(e+h*f-p[0],u+x*f-p[1])<=n)return f/s.simHz}return 1/0}export function cueLit(t,o,r){return arrivalIn(t,o,r)<=s.pose.jump.manual.cueLead}let c=null;export function autoJump(){if(c===null){c=!1;try{const t=localStorage.getItem(s.storage.jump);t&&(c=JSON.parse(t).auto===!0)}catch{}}return c}export function setAutoJump(t){c=!!t;try{localStorage.setItem(s.storage.jump,JSON.stringify({auto:c}))}catch{}return c}export function resetAutoJump(){c=null}
